  critical_thinking_scientific: {
    pt: [
      { id:"q3", question:"O que é um estudo duplo-cego?", options:["Um experimento sem hipótese","Um estudo onde nem participantes nem pesquisadores sabem quem recebeu tratamento real","Um experimento com dois grupos de controle","Um método que usa apenas dados qualitativos"], answerIndex:1, explanation:"No duplo-cego, tanto participantes quanto pesquisadores desconhecem quem recebeu o tratamento real, eliminando o efeito placebo e o viés do observador." },
      { id:"q4", question:"O que distingue uma teoria científica de uma hipótese?", options:["Uma teoria é uma ideia não testada; uma hipótese já foi comprovada","Uma teoria é uma explicação ampla sustentada por muitas evidências; uma hipótese é uma previsão a testar","São sinônimos","Uma teoria usa matemática; uma hipótese não"], answerIndex:1, explanation:"Teoria científica não é palpite — é explicação robusta sustentada por evidências acumuladas. Hipótese é previsão específica antes de ser testada." },
      { id:"q5", question:"Por que a revisão por pares é essencial para a ciência?", options:["Garante que só cientistas famosos publiquem","Permite que especialistas avaliem metodologia e resultados antes da publicação","Torna a ciência mais rápida","Impede publicação de resultados negativos"], answerIndex:1, explanation:"A revisão por pares funciona como controle de qualidade: especialistas verificam se o método é sólido e as conclusões justificadas antes de se tornarem conhecimento científico." },
    ],
    en: [
      { id:"q3", question:"What is a double-blind study?", options:["An experiment without a hypothesis","A study where neither participants nor researchers know who received the real treatment","An experiment with two control groups","A method using only qualitative data"], answerIndex:1, explanation:"In a double-blind study, both participants and researchers are unaware of who received the real treatment, eliminating placebo effect and observer bias." },
      { id:"q4", question:"What distinguishes a scientific theory from a hypothesis?", options:["A theory is an untested idea; a hypothesis has been proven","A theory is a broad explanation supported by much evidence; a hypothesis is a specific prediction to test","They are synonyms","A theory uses math; a hypothesis doesn't"], answerIndex:1, explanation:"A scientific theory is not a guess — it's a robust explanation supported by accumulated evidence. A hypothesis is a specific prediction before testing." },
      { id:"q5", question:"Why is peer review essential for science?", options:["It ensures only famous scientists publish","It allows experts to evaluate methodology and results before publication","It makes science faster","It prevents publication of negative results"], answerIndex:1, explanation:"Peer review acts as quality control: experts verify whether the method is sound and conclusions justified before becoming scientific knowledge." },
    ],
    es: [
      { id:"q3", question:"¿Qué es un estudio doble ciego?", options:["Un experimento sin hipótesis","Un estudio en que ni los participantes ni los investigadores saben quién recibió el tratamiento real","Un experimento con dos grupos de control","Un método que usa solo datos cualitativos"], answerIndex:1, explanation:"En el doble ciego, tanto participantes como investigadores desconocen quién recibió el tratamiento real, eliminando el efecto placebo y el sesgo del observador." },
      { id:"q4", question:"¿Qué distingue una teoría científica de una hipótesis?", options:["Una teoría es una idea no probada; una hipótesis ya fue comprobada","Una teoría es una explicación amplia respaldada por muchas evidencias; una hipótesis es una predicción a probar","Son sinónimos","Una teoría usa matemáticas; una hipótesis no"], answerIndex:1, explanation:"La teoría científica no es una suposición — es una explicación robusta respaldada por evidencias acumuladas. La hipótesis es una predicción específica antes de ser probada." },
      { id:"q5", question:"¿Por qué la revisión por pares es esencial para la ciencia?", options:["Garantiza que solo los científicos famosos publiquen","Permite que expertos evalúen metodología y resultados antes de la publicación","Hace la ciencia más rápida","Impide la publicación de resultados negativos"], answerIndex:1, explanation:"La revisión por pares actúa como control de calidad: expertos verifican si el método es sólido y las conclusiones están justificadas antes de convertirse en conocimiento científico." },
    ],
  },

