// ─── PATCH FUNCTION ────────────────────────────────────────────────────────────

async function patchPack(packId, lang) {
  const newQs = NEW_QUESTIONS[packId]?.[lang];
  if (!newQs) {
    console.log(`  ⚠️  No new questions defined for ${packId}/${lang} — skipping`);
    return;
  }

  // Find the file in Storage
  const [files] = await bucket.getFiles({ prefix: `packs/${packId}/` });
  const file = files.find(f => f.name === `packs/${packId}/v1/${lang}.json`) ||
               files.find(f => f.name.endsWith(`/${lang}.json`) && f.name.includes(packId));

  if (!file) {
    console.log(`  ⚠️  File not found for ${packId}/${lang}`);
    return;
  }

  const [buf] = await file.download();
  const pack = JSON.parse(buf.toString());

  if (pack.quiz.length >= 5) {
    console.log(`  ✓ ${packId}/${lang} already has ${pack.quiz.length} questions`);
    return;
  }

  pack.quiz = [...pack.quiz, ...newQs];

  await file.save(JSON.stringify(pack, null, 2), {
    contentType: "application/json",
    metadata: { cacheControl: "public, max-age=31536000" },
  });

  console.log(`  ✓ ${packId}/${lang}: ${pack.quiz.length} questions`);
}

async function main() {
  const packIds = Object.keys(NEW_QUESTIONS);
  const langs = ["pt", "en", "es"];

  for (const packId of packIds) {
    console.log(`\n📦 ${packId}`);
    for (const lang of langs) {
      await patchPack(packId, lang);
    }
  }

  console.log("\n✅ Done");
  process.exit(0);
}

main().catch(e => { console.error(e); process.exit(1); });
